import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"關於與更新","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/about.md","filePath":"zh-HK/user-guide/settings/about.md","lastUpdated":1787586465000}'),s={name:"zh-HK/user-guide/settings/about.md"};function i(n,a,l,d,c,h){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="關於與更新" tabindex="-1">關於與更新 <a class="header-anchor" href="#關於與更新" aria-label="Permalink to &quot;關於與更新&quot;">​</a></h1><p>關於頁面提供了 Lertaro 當前執行環境的完整版本資訊、使用者與系統資料儲存目錄的快速直達入口，以及線上檢查更新與一鍵無縫升級功能。頁面路徑為<strong>設定 → 關於</strong>。</p><h2 id="_1-元件版本與專案資訊" tabindex="-1">1. 元件版本與專案資訊 <a class="header-anchor" href="#_1-元件版本與專案資訊" aria-label="Permalink to &quot;1. 元件版本與專案資訊&quot;">​</a></h2><p>頁面頂部展示了 Lertaro 架構體系中四大核心元件的獨立版本號：</p><ul><li><strong>App 版本</strong>：前景 WPF 使用者互動介面版本。</li><li><strong>Core 版本</strong>：核心搜尋與索引運算邏輯庫版本。</li><li><strong>Service 版本</strong>：後台 Windows 索引服務版本（其文字顏色會動態反映服務當前是否處於健康連線狀態）。</li><li><strong>CLI 版本</strong>：命令列終端互動工具 <code>lff</code> 的版本。</li></ul><p>下方提供了專案官方網站、GitHub 開源存放庫以及線上文件中心的直達連結。</p><h2 id="_2-資料目錄與自動備份輪轉機制" tabindex="-1">2. 資料目錄與自動備份輪轉機制 <a class="header-anchor" href="#_2-資料目錄與自動備份輪轉機制" aria-label="Permalink to &quot;2. 資料目錄與自動備份輪轉機制&quot;">​</a></h2><p>頁面中央提供了兩個直接可點擊開啟實體路徑的超連結（若目標資料夾尚未產生，點擊時會自動建立）：</p><h3 id="使用者資料目錄-user-data-directory" tabindex="-1">使用者資料目錄（User Data Directory） <a class="header-anchor" href="#使用者資料目錄-user-data-directory" aria-label="Permalink to &quot;使用者資料目錄（User Data Directory）&quot;">​</a></h3><ul><li><strong>儲存內容</strong>：存放當前 Windows 使用者的個人設定檔 <code>user-settings.json</code>、搜尋與關鍵字歷程記錄、使用者專屬快取及憑證。</li><li><strong>五級備份輪轉保護機制</strong>：每次在設定中心點擊儲存或修改設定時，Lertaro 會自動將現有設定檔順延輪轉備份為 <code>user-settings.json.bak.1</code>，舊的備份依次向後推移至 <code>user-settings.json.bak.5</code>。即使發生斷電、誤改或系統當機，也能隨時在資料目錄中找到最近 5 次的歷史備份進行還原。</li></ul><h3 id="機器資料目錄-machine-data-directory" tabindex="-1">機器資料目錄（Machine Data Directory） <a class="header-anchor" href="#機器資料目錄-machine-data-directory" aria-label="Permalink to &quot;機器資料目錄（Machine Data Directory）&quot;">​</a></h3><ul><li><strong>儲存內容</strong>：存放後台提權服務使用的機器級設定檔 <code>machine-settings.json</code>、全盤實體索引持久化快取以及服務端記錄檔。</li></ul><h3 id="儲存路徑規則" tabindex="-1">儲存路徑規則 <a class="header-anchor" href="#儲存路徑規則" aria-label="Permalink to &quot;儲存路徑規則&quot;">​</a></h3><ul><li><strong>安裝版</strong>：使用者資料存放於 <code>%LocalAppData%\\Lertaro</code>，機器資料存放於 <code>%ProgramData%\\Lertaro</code>。</li><li><strong>可攜版</strong>：使用者資料存放於程式目錄下的 <code>Data\\Users\\&lt;SID hash&gt;</code>，機器資料存放於 <code>Data\\Machine</code>，實現純綠色的全隔離可攜運行（詳見<a href="./../getting-started.html#可攜版資料隔離機制"><strong>可攜版使用說明</strong></a>）。</li></ul><h2 id="_3-檢查更新與一鍵升級" tabindex="-1">3. 檢查更新與一鍵升級 <a class="header-anchor" href="#_3-檢查更新與一鍵升級" aria-label="Permalink to &quot;3. 檢查更新與一鍵升級&quot;">​</a></h2><ul><li><strong>檢查更新按鈕</strong>：點擊後手動發起線上版本偵測。按鈕文字會動態反饋檢查狀態（「正在檢查更新...」 → 「已是最新版本」 或彈出新版本更新卡片）。</li><li><strong>發現新版本時的升級方式</strong>： <ul><li><strong>無訊息自動更新</strong> —— 在後台自動下載新版本安裝套件並就地無縫覆蓋升級，升級完成後自動重啟拉起 Lertaro。</li><li><strong>前往下載頁面</strong> —— 在預設瀏覽器中開啟 GitHub Releases 發布頁面，供手動下載可攜壓縮包或安裝程式。</li></ul></li><li><strong>權限安全提示</strong>：若當前運行在受限的標準使用者帳戶下，且無法直接停用後台 Windows 服務完成就地更新，頁面會呈現醒目的安全提示，並引導你前往官方頁面下載安裝。</li></ul>',16)])])}const _=t(s,[["render",i]]);export{g as __pageData,_ as default};
